#!/bin/bash
# Панель людей ZAVDANNYA-196: одна роль × один вигляд (літера — kody-panel.txt), знімки телефона з docs/makety-193/<стиль>/{karta,budynok,rayon}-tel.png, скопійовані в img/<літера>/ без назви стилю.
# $1 = роль-ключ, $2 = літера
declare -A R
R[orendar]="Тобі 25 років, ти орендуєш квартиру в Києві й зараз шукаєш нову; дивишся сайти з телефона в метро, нетерплячий, звик до сучасних застосунків; бюджет обмежений."
R[simia]="Ви — подружжя близько 35 років з дитиною 6 років, купуєте квартиру в Києві за великі для вас гроші; уважно перевіряєте все перед покупкою, боїтеся, щоб вас не обдурили."
R[pensionerka]="Вам 68 років, ви пенсіонерка, все життя живете на Подолі; дивитеся сайт з телефона онуки, зір уже не дуже, дрібний текст читаєте з окулярами; не любите незрозумілих слів."
R[kafe]="Вам 41 рік, ви власник невеликої кав'ярні біля станції метро; думаєте, чи відкривати другу точку і що відбувається довкола; рахуєте гроші, не любите маркетингових штучок."
R[zhurnalist]="Вам 32 роки, ви журналіст київського онлайн-медіа, пишете про міські теми; перевіряєте джерела, скептичні до «карт злочинності», шукаєте готові візуали з цифрами для статті."
ROLE="${R[$1]}"
D=$(pwd)/img/$2
P="Ти граєш роль реальної людини. ${ROLE}
Тобі показали сайт «Моя вулиця»: карта подій Києва, складена з рішень судів, і скарги на гарячу лінію 1551 по кожному будинку. Безкоштовно — скільки подій; за гроші — довідка про будинок 199 грн, повний звіт 299 грн, підписка 399 грн/міс з адресами й описами.
Переглянь три знімки екрана телефона (прочитай файли): ${D}/karta.png (карта міста з карткою соти), ${D}/budynok.png (сторінка будинку), ${D}/rayon.png (сторінка району).
Оцінюй саме ВИГЛЯД і зрозумілість (дані в усіх варіантах однакові). Говори від першої особи, чесно, як ця людина, без ввічливих компліментів. Не вигадуй того, чого не бачиш.
Відповідай ЛИШЕ одним JSON без markdown, українською:
{\"zrozumilo\": \"що зрозуміло з першого погляду і що ні (1-2 речення)\", \"kolir_oznachaie\": \"що, на твою думку, означає колір сот на карті\", \"liakaie\": \"так/ні — чи виглядає як карта небезпеки, і чому\", \"viryu\": 1-5, \"chomu_viryu\": \"одне речення\", \"zaplatyv_by\": \"так/можливо/ні\", \"chomu_zaplatyv\": \"одне речення\", \"chytabelno\": 1-5, \"dratuie\": \"що дратує (1 речення)\", \"podobaietsia\": \"що подобається (1 речення)\", \"zahalom\": 1-5}"
cd "$D" && timeout 300 claude -p "$P" --allowedTools Read > "$(dirname $(dirname $D))/vidp/$1-$2.json" 2>&1
